UPDATE comment SET like_count = like_count + CASE id

    WHEN #{item.id} THEN #{item.incrCount}

END
WHERE id IN

    #{item.id}

UPDATE comment
SET reply_count = COALESCE(reply_count,0) + 1
WHERE id = #{rootId}
    AND post_id = #{postId}
    AND deleted = 0

UPDATE comment
SET reply_count = GREATEST(COALESCE(reply_count, 0) - 1, 0)
WHERE id = #{rootId}
  AND post_id = #{postId}
  AND deleted = 0
